data class GeneratedEngineResponse(
    val requestId: String,
    val ok: Boolean,
    val value: Any?,
    val errorCode: String? = null,
    val errorMessage: String? = null,
) {
    companion object {
        fun fromJson(envelope: JSONObject): GeneratedEngineResponse {
            require(envelope.optString(EngineContract.TYPE) == EngineContract.EVENT_RESPONSE) {
                "Expected engine response event"
