            val requestId = envelope.optString(EngineContract.REQUEST_ID)
            require(requestId.isNotBlank()) { "Engine response is missing requestId" }
            val result = envelope.optJSONObject(EngineContract.RESULT)
                ?: error("Engine response is missing result envelope")
            return when (val status = result.optString(EngineContract.STATUS)) {
                EngineContract.RESPONSE_STATUS_OK -> GeneratedEngineResponse(
                    requestId = requestId,
                    ok = true,
                    value = decodeGeneratedPayload(
                        result.optJSONObject(EngineContract.PAYLOAD)
                            ?: error("Engine response is missing payload envelope"),
                    ),
                )
                EngineContract.RESPONSE_STATUS_ERROR -> GeneratedEngineResponse(
                    requestId = requestId,
                    ok = false,
                    value = null,
                    errorCode = result.optString(EngineContract.CODE).takeIf { it.isNotBlank() },
                    errorMessage = result.optString(EngineContract.MESSAGE).takeIf { it.isNotBlank() },
                )
                else -> error("Unknown engine response status: $status")
            }
        }
    }
}

private fun decodeGeneratedPayload(payload: JSONObject): Any? = when (val type = payload.optString(EngineContract.TYPE)) {
        EngineContract.RESPONSE_PAYLOAD_EMPTY -> null
        EngineContract.RESPONSE_PAYLOAD_JSON -> normalizeGeneratedJson(
            payload.opt(EngineContract.VALUE),
        )
        else -> error("Unknown engine response payload type: $type")
    }

private fun normalizeGeneratedJson(value: Any?): Any? = when (value) {
    null, JSONObject.NULL -> null
    is JSONObject -> value.keys().asSequence().associateWith { key ->
        normalizeGeneratedJson(value.opt(key))
    }
    is JSONArray -> List(value.length()) { index ->
        normalizeGeneratedJson(value.opt(index))
    }
    else -> value
}


